// Renders the HTML documents under docs/ into PDFs, using the Chromium that
// Playwright already installs for the e2e suite. Kept out of the build: the PDFs
// are committed artifacts, regenerated by hand when their source HTML changes.
//
//   npm run docs:pdf
//
// Add a new document by appending to DOCS below.
// cspell:ignore networkidle
import { chromium } from '@playwright/test';
import { pathToFileURL, fileURLToPath } from 'node:url';
import { resolve, dirname } from 'node:path';
import { access } from 'node:fs/promises';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');

const DOCS = [
  {
    source: 'docs/architecture/architecture.html',
    output: 'docs/architecture/kairosflow-architecture.pdf',
  },
];

async function render(browser, doc) {
  const sourcePath = resolve(root, doc.source);
  await access(sourcePath);

  const page = await browser.newPage();
  await page.goto(pathToFileURL(sourcePath).href, { waitUntil: 'networkidle' });
  await page.emulateMedia({ media: 'print' });
  await page.pdf({
    path: resolve(root, doc.output),
    // The document declares its own @page size (A4 landscape) and margins.
    preferCSSPageSize: true,
    printBackground: true,
  });
  await page.close();
  process.stdout.write(`${doc.source} -> ${doc.output}\n`);
}

const browser = await chromium.launch();
try {
  for (const doc of DOCS) await render(browser, doc);
} finally {
  await browser.close();
}
